actions.script:
grn = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId', grnId).disableAuthz().one()
def access = grn ? ec.service.sync().name('zenith.purchase.OperationsServices.assert#PurchaseOrder')
    .parameters([orderId:grn.purchaseOrderId, errorOnDenied:'N']).call() : null
allowed = scope.organizationPartyId && access?.allowed && access.part.customerPartyId == scope.organizationPartyId && grn.vendorPartyId == access.part.vendorPartyId
order = allowed ? access.order : null
canSend = allowed && (order.statusId in ['OrderApproved','OrderCompleted']) &&
    (access.part.statusId in ['OrderApproved','OrderCompleted'])
if (allowed && !canSend && (!grn.statusId || grn.statusId == 'GrnDraft')) {
    def target = [OrderOpen:'OrderPlaced', OrderProposed:'OrderPlaced',
                  OrderPlaced:'OrderApproved', OrderProcessing:'OrderApproved'][order.statusId]
    def transition = target ? ec.entity.find('moqui.basic.StatusFlowTransition')
        .condition('statusFlowId','Default').condition('statusId',order.statusId)
        .condition('toStatusId',target).one() : null
    if (transition && (!transition.userPermissionId || ec.user.hasPermission(transition.userPermissionId))) {
        approvalAction = target == 'OrderPlaced' ? 'placePo' : 'approvePo'
    }
}
if (!allowed) grn = null

def grn = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId', grnId).forUpdate(true).one()
if (grn.statusId == 'GrnCancelled') { ec.message.addError('Cancelled GRNs cannot be edited.'); return }
if (grn.statusId && grn.statusId != 'GrnDraft' && grn.facilityId != facilityId) {
    ec.message.addError('The receiving location cannot change after submission.'); return
}
def orgId = ec.user.getPreference('ACTIVE_ORGANIZATION')
def facility = ec.entity.find('mantle.facility.Facility').condition('facilityId', facilityId).one()
if (facility?.ownerPartyId != orgId) { ec.message.addError('Choose a receiving location from your organization.'); return }
def reference = vendorInvoiceNumber?.toString()?.trim()
if (reference && (reference.length() > 50 || reference.any { Character.isISOControl(it as char) })) {
    ec.message.addError('Enter an invoice number of up to 50 characters.'); return
}
if (invoiceId) {
    def bill = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one()
    if (!bill || bill.invoiceTypeEnumId != 'InvoicePurchase' || bill.toPartyId != orgId || bill.fromPartyId != grn.vendorPartyId ||
            bill.currencyUomId != access.order.currencyUomId || bill.statusId == 'InvoiceCancelled') {
        ec.message.addError('Choose a purchase invoice for this supplier, organization and PO currency.'); return
    }
    if (reference && bill.vendorInvoiceNumber && reference != bill.vendorInvoiceNumber) {
        ec.message.addError('The invoice number must match the selected vendor bill.'); return
    }
    reference = bill.vendorInvoiceNumber ?: reference
}
grn.setAll([facilityId:facilityId, invoiceId:invoiceId ?: null, vendorInvoiceNumber:reference ?: null, statusId:grn.statusId ?: 'GrnDraft']).update()
ec.message.addMessage('GRN details saved.')

def grn = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId', grnId).forUpdate(true).one()
if (grn.statusId && grn.statusId != 'GrnDraft') { ec.message.addError('Only draft GRNs can be edited.'); return }
if ([plannedQuantity,unitAmount].any { it < 0G || it.stripTrailingZeros().scale() > 6 || it.precision() - it.scale() > 20 }) {
    ec.message.addError('Quantity and unit cost must be nonnegative numbers with up to 6 decimal places.'); return
}
def item = ec.entity.find('mantle.order.OrderItem').condition('orderId', grn.purchaseOrderId).condition('orderItemSeqId', orderItemSeqId).one()
def product = item?.productId ? ec.entity.find('mantle.product.Product').condition('productId', item.productId).one() : null
if (item?.orderPartSeqId != '01' || product?.ownerPartyId != ec.user.getPreference('ACTIVE_ORGANIZATION')) {
    ec.message.addError('Choose a product line from this purchase order.'); return
}
if (plannedQuantity > (item.quantity ?: 0G) - (item.quantityCancelled ?: 0G)) {
    ec.message.addError('The delivery quantity exceeds the purchase order quantity.'); return
}
def line = ec.entity.find('zenith.erp.purchase.GoodsReceiptNoteItem').condition('grnId', grnId).condition('itemSeqId', orderItemSeqId).one()
if (line && !line.orderItemSeqId) { ec.message.addError('This legacy GRN line must be reviewed before editing.'); return }
if (plannedQuantity == 0G) { if (line) line.delete(); return }
if (!line) line = ec.entity.makeValue('zenith.erp.purchase.GoodsReceiptNoteItem').setAll([grnId:grnId,itemSeqId:orderItemSeqId])
def existing = line.orderItemSeqId != null
line.setAll([orderItemSeqId:orderItemSeqId,productId:item.productId,plannedQuantity:plannedQuantity,unitAmount:unitAmount])
if (existing) line.update()
else line.set('inventoryReceivedQuantity',0G).create()
ec.message.addMessage('Delivery line saved. Enter zero quantity to remove a draft line.')

if (!(draftAction in ['save','send','placePo','approvePo'])) { ec.message.addError('Choose a delivery action.'); return }
// Use the same lock order as inventory confirmation and GRN submission.
def order = ec.entity.find('mantle.order.OrderHeader').condition('orderId',access.grn.purchaseOrderId)
    .forUpdate(true).useCache(false).one()
def approvalTarget = [placePo:'OrderPlaced', approvePo:'OrderApproved'][draftAction]
if (approvalTarget && (access.approvalAction != draftAction || order.statusId != access.order.statusId)) {
    ec.message.addError('The purchase order status has changed or this action is unavailable. Reload the GRN.'); return
}
def current = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId',grnId).forUpdate(true).useCache(false).one()
if ((current.statusId && current.statusId != 'GrnDraft') || current.lastUpdatedStamp.time.toString() != draftVersion) {
    ec.message.addError('This delivery has changed. Reload it before saving.'); return
}
def savedLines = ec.entity.find('zenith.erp.purchase.GoodsReceiptNoteItem').condition('grnId',grnId).list()
    .collectEntries { [(it.itemSeqId):it] }
if (!lines.keySet().containsAll(savedLines.keySet())) {
    ec.message.addError('The delivery products have changed. Reload before saving.'); return
}
for (entry in lines) {
    def previous = savedLines[entry.key]
    def input = entry.value
    if (!(input instanceof Map) || input.version != (previous?.lastUpdatedStamp?.time?.toString() ?: '') || (previous && !previous.orderItemSeqId)) {
        ec.message.addError('A delivery line has changed or needs review. Reload before saving.'); return
    }
    BigDecimal qty, cost
    try {
        qty = new BigDecimal(input.quantity?.toString() ?: '')
        if (!previous && qty == 0G) continue
        cost = qty == 0G ? 0G : new BigDecimal(input.cost?.toString() ?: '')
    } catch (NumberFormatException ignored) {
        ec.message.addError('Enter a quantity and a unit cost for each included product.'); return
    }
    if (previous && previous.plannedQuantity == qty && previous.unitAmount == cost) continue
    ec.service.sync().name('zenith.purchase.GoodsReceiptServices.save#GoodsReceiptLine')
        .parameters([grnId:grnId,orderItemSeqId:entry.key,plannedQuantity:qty,unitAmount:cost]).call()
    if (ec.message.hasError()) return
}
ec.service.sync().name('zenith.purchase.GoodsReceiptServices.save#GoodsReceiptDetails')
    .parameters([grnId:grnId,facilityId:facilityId,vendorInvoiceNumber:vendorInvoiceNumber,invoiceId:invoiceId]).call()
if (!ec.message.hasError() && draftAction == 'send') {
    ec.service.sync().name('zenith.purchase.GoodsReceiptServices.submit#GoodsReceipt').parameters([grnId:grnId]).call()
}
if (!ec.message.hasError() && approvalTarget) {
    ec.service.sync().name('zenith.purchase.OperationsServices.update#PurchaseOrder')
        .parameters([orderId:order.orderId, updates:[statusId:approvalTarget]]).call()
}

// PO first is the same lock order used by Inventory receipt confirmation.
def order = ec.entity.find('mantle.order.OrderHeader').condition('orderId', access.grn.purchaseOrderId).forUpdate(true).useCache(false).one()
def grn = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId', grnId).forUpdate(true).useCache(false).one()
if (grn.statusId in ['GrnPending','GrnPartial','GrnReceived']) return
if (grn.statusId && grn.statusId != 'GrnDraft') { ec.message.addError('Only draft GRNs can be submitted.'); return }
def part = ec.entity.find('mantle.order.OrderPart').condition('orderId',order.orderId).condition('orderPartSeqId','01').one()
if (!(order.statusId in ['OrderApproved','OrderCompleted']) || !(part.statusId in ['OrderApproved','OrderCompleted'])) {
    ec.message.addError('Approve the purchase order before submitting this GRN to Inventory.'); return
}
def facility = grn.facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId',grn.facilityId).one() : null
if (facility?.ownerPartyId != part.customerPartyId) { ec.message.addError('Save a receiving location before submitting.'); return }
def lines = ec.entity.find('zenith.erp.purchase.GoodsReceiptNoteItem').condition('grnId',grnId).list()
if (!lines) { ec.message.addError('Add at least one delivery product and quantity.'); return }
def received = ec.service.sync().name('zenith.inventory.ReceiptServices.get#OrderReceiptQuantities').parameters([orderId:order.orderId]).call().receivedByItem
def reserved = ec.service.sync().name('zenith.inventory.ReceiptServices.get#PendingGrnQuantities').parameters([orderId:order.orderId]).call().reservedByItem
def seen = new HashSet()
for (line in lines) {
    def item = line.orderItemSeqId ? ec.entity.find('mantle.order.OrderItem').condition('orderId',order.orderId).condition('orderItemSeqId',line.orderItemSeqId).one() : null
    def product = item?.productId ? ec.entity.find('mantle.product.Product').condition('productId',item.productId).one() : null
    if (!item || item.orderPartSeqId != '01' || !seen.add(line.orderItemSeqId) || product?.ownerPartyId != part.customerPartyId ||
            line.productId != item.productId || !line.plannedQuantity || line.plannedQuantity <= 0G || line.unitAmount == null || line.unitAmount < 0G) {
        ec.message.addError('Every delivery line must contain a valid PO product, positive quantity and unit cost.'); return
    }
    def remaining = (item.quantity ?: 0G) - (item.quantityCancelled ?: 0G) - (received[line.orderItemSeqId] ?: 0G) - (reserved[line.orderItemSeqId] ?: 0G)
    if (line.plannedQuantity > remaining) { ec.message.addError('Delivery quantity exceeds the unallocated PO balance for ' + line.orderItemSeqId + '.'); return }
}
if (ec.message.hasError()) return
grn.set('statusId','GrnPending').update()
ec.message.addMessage('GRN submitted. Confirm the delivered quantities in Inventory → Receiving.')

ec.entity.find('mantle.order.OrderHeader').condition('orderId',access.grn.purchaseOrderId).forUpdate(true).one()
def grn = ec.entity.find('zenith.erp.purchase.GoodsReceiptNote').condition('grnId',grnId).forUpdate(true).one()
if (grn.statusId == 'GrnCancelled') return
if (grn.statusId && !(grn.statusId in ['GrnDraft','GrnPending','GrnPartial'])) { ec.message.addError('This GRN cannot be cancelled.'); return }
grn.set('statusId','GrnCancelled').update()
ec.message.addMessage('Outstanding delivery cancelled. Quantities already received stay in stock.')
